package com.theone.cinema;
import android.content.Context;
import org.json.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
final class MediaRepository {
 private final String server,token;
 MediaRepository(Context c)throws Exception{try(InputStream in=c.getAssets().open("private_cinema.json")){JSONObject x=new JSONObject(read(in));server=x.getString("relay_url");token=x.getString("relay_token");}if(!server.startsWith("https://rubenvanaggelen.com/")||token.isEmpty())throw new IOException("Source unavailable");}
 private static String enc(String s){try{return URLEncoder.encode(s,"UTF-8").replace("+","%20");}catch(Exception e){throw new IllegalArgumentException();}}
 private String api(String action,String extra)throws Exception{String query=action.equals("get_series_info")?"action=episodes"+extra.replace("series_id", "id"):"action=catalog&type="+(action.equals("get_series")?"series":"movies");HttpURLConnection c=(HttpURLConnection)new URL(server+"?"+query).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(60000);c.setRequestProperty("X-Cinema-Token",token);try{if(c.getResponseCode()!=200)throw new IOException("Catalog unavailable");return read(c.getInputStream());}finally{c.disconnect();}}
 private static String read(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>100*1024*1024)throw new IOException("Catalog exceeds limit");}return out.toString("UTF-8");}
 List<CatalogEntry> load(String type)throws Exception{JSONArray array=new JSONArray(api(type.equals("series")?"get_series":"get_vod_streams",""));List<CatalogEntry> list=new ArrayList<>();for(int i=0;i<array.length();i++){JSONObject x=array.optJSONObject(i);if(x==null||x.optInt("is_adult",0)==1)continue;int id=x.optInt(type.equals("series")?"series_id":"stream_id");String title=x.optString("name");if(id>0&&!title.isEmpty())list.add(new CatalogEntry(id,title,x.optString("container_extension","mp4"),x.optString("stream_icon",x.optString("cover")),x.optString("category_id"),type,x.optLong(type.equals("series")?"last_modified":"added",0)));}list.sort((a,b)->Long.compare(b.added,a.added));return list;}
 List<CatalogEntry> episodes(CatalogEntry entry)throws Exception{JSONObject data=new JSONObject(api("get_series_info","&series_id="+entry.id));JSONObject seasons=data.optJSONObject("episodes");List<CatalogEntry> out=new ArrayList<>();if(seasons==null)return out;List<String> keys=new ArrayList<>();seasons.keys().forEachRemaining(keys::add);keys.sort(Comparator.comparingInt(s->{try{return Integer.parseInt(s);}catch(Exception e){return 0;}}));for(String season:keys){JSONArray list=seasons.optJSONArray(season);if(list==null)continue;for(int i=0;i<list.length();i++){JSONObject x=list.optJSONObject(i);if(x==null)continue;int id=x.optInt("id");if(id>0)out.add(new CatalogEntry(id,entry.title+" · S"+season+" E"+x.optInt("episode_num",i+1)+" · "+x.optString("title"),x.optString("container_extension","mp4"),entry.poster,entry.category,"episode",entry.added));}}return out;}
 Map<String,String> streamHeaders(){return Collections.singletonMap("X-Cinema-Token",token);}
 String stream(CatalogEntry x){return server+"?action=stream&id="+x.id+"&ext="+x.extension+"&type="+(x.isEpisode()?"series":"movies");}
}
